[210741] = {name = "[q3]全自動懲戒錘", additional_info = "拾取後綁定{雙手} {權杖}\n53 - 85傷害 速度 2.00\n（每秒傷害34.50）\n+22 力量\n+8 敏捷\n耐久: 100 / 100 職業： 聖騎士 , 薩滿 , 德魯伊\n需要等級 40\n[q2]裝備： 在獵豹、熊和巨熊形態下的攻擊強度提高69點。\n[q2]使用: 使你的攻擊速度提高50%，持續30秒。無法作用於55級以上的角色。 (3分鐘 冷卻)\n[q]\"今年的型號為了提升實用性而做了多項改良。\""},
[210746] = {name = "[q2]大地之盾符文", additional_info = "拾取後綁定\n唯一\n職業： 薩滿\n[q2]在你的束褲上紋刻大地之盾符文：\n\n\n以大地護盾保護一個目標，使被保護者因受傷而損失的施法或引導時間縮短30%，並在受到攻擊時恢復受保護的目標[28 * (29.888200 + 0.690312 * 60 + 0.136267 * 60 * 60) / 100]點生命力。此效果每幾秒只能發動一次。總共可使用9次。持續10分鐘。同一時間內只能對一個目標施放大地護盾。\n[q]\"教你學會一個新紋刻技能。\""},
[210763] = {name = "奧提克樹枝", additional_info = "拾取後綁定\n唯一\n[q]\"力量的分裂殘片。看來它曾是一把強大武器的另一半。\""},
[210765] = {name = "德斯寶珠", additional_info = "拾取後綁定\n唯一\n[q]\"烈焰與黑暗魔法自寶珠中流竄而出，令人著迷，卻也引起深深的擔憂。看來它曾是一把強大武器的另一半。\""},
[210771] = {name = "[q2]伏擊物資:銅錠", additional_info = "拾取後綁定\n唯一：[Waylaid Shipment]（12）\n[q2]使用: 加入20個銅錠以完成輸送。"},
[210772] = {name = "[q2]物資輸送:銅錠", additional_info = "拾取後綁定\n唯一：[Supply Shipment]（1）\n[q]\"遞交給物資官能獲得豐厚報酬。\""},
[210773] = {name = "[q3]第二次大戰披肩", additional_info = "裝備後綁定\n{肩部} {鎖甲}\n163護甲\n+8 耐力\n耐久: 70 / 70\n需要等級 25\n[q2]裝備： 提高神聖法術和效果所造成的傷害，最多11點。"},
[210779] = {name = "[q2]設計圖:第二次大戰披肩", additional_info = "拾取後綁定\n需要 鍛造 (150)\n[q2]使用: 教你學會如何製作第二次大戰披肩。\n[q3]第二次大戰披肩\n裝備後綁定\n{肩部} {鎖甲}\n163護甲\n+8 耐力\n耐久: 70 / 70\n需要等級 25\n[q2]裝備： 提高神聖法術和效果所造成的傷害，最多11點。\n需要 青銅錠 (20), 綠瑪瑙 (2), 次級月亮石 (2), 彩色珍珠 (2), 銀錠 (4)"},
[210781] = {name = "[q3]鳳凰束腕", additional_info = "裝備後綁定\n{手腕} {布甲}\n21護甲\n耐久: 30 / 30\n需要等級 25\n[q2]裝備： 提高火焰法術和效果所造成的傷害，最多13點。"},
[210794] = {name = "[q4]移形銀鱗胸甲", additional_info = "拾取後綁定\n僅可裝備一件：[Void-Touched]（1）\n{胸部} {鎖甲}\n238護甲\n+12 力量\n+5 耐力\n耐久: 145 / 145\n需要等級 25\n需要 鍛造 (100)\n[q2]裝備： 此物品被注入了虛空的原始力量。當持有者遭到攻擊時，此物品有很高的機率會降下駭人的詛咒，使攻擊者受到的所有傷害額外提高，持續15秒。（特效觸發機率：25%）\n[q2]裝備： 使你的所有攻擊和法術命中的機率提高1%。"},
[210795] = {name = "[q4]殊界蛛絲之靴", additional_info = "拾取後綁定\n僅可裝備一件：[Void-Touched]（1）\n{腳} {布甲}\n35護甲\n+5 耐力\n+5 智力\n+6 精神\n耐久: 50 / 50\n需要等級 25\n需要 裁縫 (100)\n[q2]使用: 暫時進入另一個界域，立即降低威脅值，並使承受的所有傷害與造成的傷害降低30%，持續6秒。 (10分鐘 冷卻)\n[q2]裝備： 使魔法法術和效果所造成的傷害和治療效果提高最多7點。\n[q2]裝備： 使你的所有攻擊和法術命中的機率提高1%。"},
[210811] = {name = "[q2]原初之怒符文", additional_info = "拾取後綁定\n唯一\n職業： 薩滿\n[q2]在你的束褲上紋刻強效鬼魂之狼符文：\n\n\n你的鬼魂之狼現在能在室內使用，並且在生效期間使你受到的所有傷害降低10%。\n[q]\"教你學會一個新紋刻技能。\""},
[210817] = {name = "[q2]生存符文", additional_info = "拾取後綁定\n唯一\n職業： 德魯伊\n[q2]在你的護胸或長袍上紋刻適者生存符文：\n\n\n使你被近戰攻擊時造成致命一擊的機率降低6%，並使你受到的所有傷害降低10%。在熊形態或巨熊形態下受到的傷害會額外降低10%。\n[q]\"教你學會一個新紋刻技能。\""},
[210818] = {name = "[q2]孤狼符文", additional_info = "拾取後綁定\n唯一\n職業： 獵人\n[q2]在你的護胸或長袍上紋刻孤狼符文：\n\n\n當你沒有啟用寵物時，你所有攻擊造成的傷害提高25%。\n[q]\"教你學會一個新紋刻技能。\""},
[210820] = {name = "[q2]犧牲符文", additional_info = "拾取後綁定\n唯一\n職業： 聖騎士\n[q2]在你的褲子上紋刻犧牲聖禦符文：\n\n\n使目標隊伍或團隊成員受到的30%傷害轉移至施法者身上，可持續12秒或直到轉移相當於施法者生命力上限100%的傷害為止。\n[q]\"教你學會一個新紋刻技能。\""},
[210822] = {name = "[q2]和諧顯聖", additional_info = "拾取後綁定\n唯一\n職業： 牧師\n[q2]在你的護胸或長袍上紋刻機緣回復符文：\n\n\n使用快速治療會使你下一次的次級治療術、治療術、強效治療術或治療禱言的施法時間縮短20%，持續20秒，並可最多疊加3次。\n[q]\"學會一個新紋刻技能。\""},
[210823] = {name = "[q2]雙武器專精符文", additional_info = "拾取後綁定\n唯一\n職業： 薩滿\n[q2]在你的護胸或長袍上紋刻雙武器專精符文：\n\n\n當你雙持武器時，你同時以法術和近戰攻擊的機率提高5%，你的風暴打擊技能會以所持的兩把武器進行攻擊，同時提升你副手武器的傷害60%。\n[q]\"教你學會一個新紋刻技能。\""},
[210824] = {name = "[q2]契印符文", additional_info = "拾取後綁定\n唯一\n職業： 術士\n[q2]在你的束褲上紋刻惡魔契印符文：\n\n\n你的火焰與暗影法術額外造成10%傷害，且你寵物的致命一擊會為你的隊伍或團隊成員施加惡魔契印效果，持續45秒。惡魔契印會使法術傷害與治療效果提高相當於你法術傷害的10%或( 60 / 2)點，取較高者計。無法在制伏中的惡魔身上生效。\n[q]\"教你學會一個新紋刻技能。\""},
[210825] = {name = "[q2]戰爭使者符文", additional_info = "拾取後綁定\n唯一\n職業： 戰士\n[q2]在你的護胸上紋刻戰爭使者符文：\n\n\n你的衝鋒、攔截和阻擾技能現在在任何姿態下都能在戰鬥中使用，啟用時還會移除所有移動限制效果。\n[q]\"教你學會一個新紋刻技能。\""},
[210953] = {name = "伯絲卡之眼", additional_info = "拾取後綁定\n唯一\n[q]\"雖然這眼睛並沒有生命存在，但你仍覺得受到注視…\""},
