[215683] = {name = "地卜術：殘酷真相", additional_info = "拾取後綁定\n唯一\n[q]\"有關元素魔法起源和運用的理論。在圖書館內會是讓人眼睛一亮的館藏。\""},
[215815] = {name = "防禦魔法基本指南", additional_info = "拾取後綁定\n唯一\n[q]\"防禦魔法與屏障的入門指南。在圖書館內會是讓人眼睛一亮的館藏。\""},
[215816] = {name = "謊言之網：神話與傳奇解密", additional_info = "拾取後綁定\n唯一\n[q]\"一篇尚未完成且聲稱蜘蛛無害的論文。儘管如此，在圖書館內會是讓人眼睛一亮的館藏。\""},
[215817] = {name = "惡魔與你", additional_info = "拾取後綁定\n唯一\n[q]\"立場偏向惡魔的奇特內容。儘管如此，在圖書館內會是讓人眼睛一亮的館藏。\""},
[215820] = {name = "木乃伊：令人討厭的不死族指南", additional_info = "拾取後綁定\n唯一\n[q]\"足以讓最英勇的戰士嚇得亡魂喪膽的一系列恐怖故事。在圖書館內會是讓人眼睛一亮的館藏。\""},
[215822] = {name = "偌啦偌啦偌啦！", additional_info = "拾取後綁定\n唯一\n[q]\"儘管紙張都被浸溼，這怪異的字跡勉強還能辨讀。在圖書館內會是讓人眼睛一亮的館藏。\""},
