[216738] = {name = "[q2]轉移手冊", additional_info = "拾取後綁定\n唯一\n職業： 盜賊\n[q2]移除目標身上現有的所有連擊點數並儲存起來，最多持續15秒。這些儲存的連擊點數會轉移到你用近戰或遠程技能命中的下一個非玩家敵人身上。\n[q]\"教你學會轉移。\""},
[216740] = {name = "[q2]秘典：智力拓展", additional_info = "拾取後綁定\n唯一\n職業： 法師\n[q2]使秘法智力的法力消耗降低50%，並使其持續時間延長50%。\n[q]\"教你學會智力拓展。\""},
[216744] = {name = "[q2]極度堅韌卷軸", additional_info = "拾取後綁定\n唯一\n職業： 牧師\n[q2]使真言術：韌的法力消耗降低50%，並使其持續時間延長50%。\n[q]\"教你學會極度堅韌。\""},
[216745] = {name = "[q2]暗影惡魔卷軸", additional_info = "拾取後綁定\n唯一\n職業： 牧師\n[q2]召喚一個暗影惡魔來攻擊目標。當暗影惡魔攻擊時施法者同時獲得5%法力，持續15秒。\n[q]\"教你學會暗影惡魔。\""},
[216746] = {name = "[q2]命令之吼手冊", additional_info = "拾取後綁定\n唯一\n職業： 戰士\n[q2]戰士發出怒吼，使半徑30碼範圍內的所有小隊成員的耐力提高2點，持續5分鐘。\n[q]\"教你學會命令之吼。\""},
[216747] = {name = "[q2]魔典：靈魂收割", additional_info = "拾取後綁定\n唯一\n職業： 術士\n[q2]每次吸取靈魂造成傷害時，你便有機會獲得額外的靈魂裂片。這個機率會在你每次未獲得靈魂裂片時提高。\n[q]\"教你學會靈魂收割。\""},
[216748] = {name = "[q2]魔典：召喚傳送門", additional_info = "拾取後綁定\n唯一\n職業： 術士\n[q2]開啟一個製造召喚傳送門的儀式。需要施法者和2名隊伍或團隊成員共同完成此儀式。所有參與召喚的玩家都必須脫離戰鬥狀態並使用右鍵點擊傳送門，並且在召喚完成之前不得移動。此傳送門可供2名隊伍或團隊成員共同使用以召喚其選定的一名隊伍或團隊成員。\n[q]\"教你學會召喚傳送門。\""},
[216764] = {name = "[q2]深層野性活頁", additional_info = "拾取後綁定\n唯一\n職業： 德魯伊\n[q2]使野性印記的法力消耗降低50%，並使其持續時間延長50%。\n[q]\"教你學會深層野性。\""},
[216767] = {name = "[q2]復活活頁", additional_info = "拾取後綁定\n唯一\n職業： 德魯伊\n[q2]復活一個死去的玩家，復活後該玩家擁有15%的生命力和法力。無法在戰鬥中使用。\n[q]\"教你學會復活。\""},
[216768] = {name = "[q2]強化祝福之證", additional_info = "拾取後綁定\n唯一\n職業： 聖騎士\n[q2]使你力量祝福、智慧祝福、救贖祝福、庇護祝福、聖光祝福和王者祝福的持續時間延長100%，並使其法力消耗降低50%。\n[q]\"教你學會強化祝福。\""},
[216769] = {name = "[q2]圖騰投射啟示", additional_info = "拾取後綁定\n唯一\n職業： 薩滿\n[q2]將你當前啟用的圖騰改變到特定位置。\n[q]\"教你學會圖騰投射。\""},
[216770] = {name = "[q2]蝮蛇守護專論", additional_info = "拾取後綁定\n唯一\n職業： 獵人\n[q2]獵人獲得蝮蛇守護，使其遠程和近戰自動攻擊可恢復法力，但造成的總傷害降低10%。此外，你每3秒可獲得法力上限10%的法力。獲得的法力值依武器攻速而定。獵人在同一時間內只能啟動一種守護。\n[q]\"教你學會蝮蛇守護。\""},
