[220164] = {name = "[q2]鬥士符文", additional_info = "拾取後綁定\n唯一\n職業： 戰士\n[q2]在你的靴子上紋刻鬥士姿態符文：\n\n\n一個攻擊型的姿態，能使你在裝備盾牌時的傷害提高10%、格檔機率提高10%，但會使你的護甲值降低30%、產生的威脅值降低30%。此外，你的自動攻擊對並未以你為目標的敵人造成傷害時，獲得的怒氣提高50%。\n\n 採取鬥士姿態時若裝備盾牌，所有在其他姿態下才能使用的技能仍可以使用。\n[q]\"教你學會一個新紋刻技能。\""},
[220165] = {name = "[q2]憤怒符文", additional_info = "拾取後綁定\n唯一\n職業： 聖騎士\n[q2]在你的頭盔上紋刻憤怒符文：\n\n\n現在你的奉獻傷害可造成致命一擊，而且你驅邪術、神聖震擊、日光、神聖憤怒和奉獻法術的傷害可獲得等同於你近戰致命一擊機率的額外致命一擊機率。\n[q]\"教你學會一個新紋刻技能。\""},
[220166] = {name = "熾炎煉獄之核", additional_info = "任務物品"},
[220167] = {name = "閃爍的墓塵", additional_info = "任務物品\n[q]\"被親愛的人們謀殺之人的安息地墓塵…\""},
[220168] = {name = "三重釀造熔岩啤酒", additional_info = "任務物品\n唯一\n[q]\"一瓶用穩定的雙手和不穩定的頭腦創造出的火焰藥劑…\""},
[220169] = {name = "信仰象徵", additional_info = "任務物品\n[q]\"一個由找到全新目的的人所贈與的信仰象徵…\""},
[220173] = {name = "[q4]異睡症", additional_info = "拾取後綁定\n僅可裝備一件：[Blood Moon]（1）\n{雙手} {劍}\n142 - 213傷害 速度 3.40\n（每秒傷害52.21）\n+15 力量\n+11 敏捷\n+28 耐力\n耐久: 120 / 120 職業： 戰士 , 聖騎士\n需要等級 50\n[q2]命中率： 使用異睡症影響目標，使其在周圍盲目地遊蕩，持續最多2秒。\n[q]\"生於夢魘\""},
[220213] = {name = "魔化生命之血", additional_info = "拾取後綁定\n唯一"},
[220214] = {name = "煉獄鍊結", additional_info = "拾取後綁定\n唯一（5）"},
[220216] = {name = "煉獄繩索", additional_info = "拾取後綁定\n[q2]使用: 弱化『無縛獵犬』凱拉菲特斯。 (30秒 冷卻)"},
[220217] = {name = "[q2]貪婪符文", additional_info = "拾取後綁定 職業： 獵人\n[q2]在你的頭盔上紋刻快速擊殺符文：\n\n\n使急速射擊的冷卻時間縮短80%，現在急速射擊也會賦予提高40%近戰攻擊速度的效果，且在你殺死可取得經驗值或榮譽值的敵人後，下一次於20秒內使用的射擊技能所造成的傷害提高20%。\n[q]\"教你學會一個新紋刻技能。\""},
[220345] = {name = "血紅巫術", additional_info = "拾取後綁定\n唯一\n[q]\"概括各種強大的血之祭儀。在圖書館內會是充滿爭議的館藏。\""},
[220346] = {name = "浪潮賢者傳說", additional_info = "拾取後綁定\n唯一\n[q]\"上面被用不平穩的手潦草地寫滿了筆記和圖表，其內容難以辨認。在圖書館內仍然會是相當不錯的館藏。\""},
[220347] = {name = "交界與秘法", additional_info = "拾取後綁定\n唯一\n[q]\"文字在書頁上遊走，阻止人們嘗試閱讀其內容。在圖書館內會是讓人百思不解的館藏。\""},
[220348] = {name = "日常禮儀", additional_info = "拾取後綁定\n唯一\n[q]\"講述初級魔法在彬彬有禮的精靈貴族社會中能發揮何種作用的指南。在圖書館內會是讓人眼睛一亮的館藏。\""},
[220349] = {name = "石壩設計圖", additional_info = "拾取後綁定\n唯一\n[q]\"堅固的建築技藝，除了最具毀滅性的災害以外都能承受。在圖書館內會是讓人眼睛一亮的館藏。\""},
[220350] = {name = "猛毒之旅", additional_info = "拾取後綁定\n唯一\n[q]\"紀載著各種能改變心智的劇毒和毒液的特性。在圖書館內會是讓人眼睛一亮的館藏。\""},
[220351] = {name = "陰暗風之靈契", additional_info = "拾取後綁定\n唯一\n[q2]使用: 使薩滿可以看到元素之靈。"},
[220352] = {name = "鋼鐵心智", additional_info = "拾取後綁定\n唯一\n[q]\"將魔法應用在冶金學、露天開採和重工業的矮人技藝。在圖書館內會是讓人獲益匪淺、但無法實踐的館藏。\""},
[220353] = {name = "咒術師寶典", additional_info = "拾取後綁定\n唯一\n[q]\"戰前的法術和秘法理論合集，但以現代用途的角度來看已嚴重過時。在圖書館內會是讓人眼睛一亮的館藏。\""},
[220360] = {name = "[q2]生命綻放符文", additional_info = "拾取後綁定\n唯一\n職業： 德魯伊\n[q2]在你的護腕上紋刻生命綻放符文：\n\n\n你的迅癒現在也會觸發生命綻放，每1秒對迅癒目標位置15碼範圍內的所有隊伍成員治療[(38.949830 + 0.606705 * 60 + 0.167780 * 60 * 60) * 16 / 100]點生命力，持續15秒。\n[q]\"教你學會一個新紋刻技能。\""},
[220375] = {name = "風之碎片", additional_info = "拾取後綁定\n唯一\n[q2]使用: 將風之碎片與元素精華相結合。可能對找出腐化聖地有所幫助。"},
[220379] = {name = "撕碎的薩滿的筆記", additional_info = "拾取後綁定\n唯一\n本物品開啟一項任務\n職業： 薩滿\n[q]\"藏促寫下的筆記，內容幾乎難以辨認。書頁似乎被什麼東西包覆著。\""},
[220446] = {name = "[q2]異界的寶藏", additional_info = "拾取後綁定\n[q2]<右鍵單擊打開>"},
[220510] = {name = "元素精華", additional_info = "任務物品 職業： 薩滿"},
