[233962] = {name = "瘋狂精煉藥劑", additional_info = "需要等級 60\n[q2]使用: 攻擊強度提高50點，持續2小時。你在同一時間內只能保有一種精煉藥劑的效果。此效果在死亡之後仍然有效。 (3秒 冷卻)"},
[233964] = {name = "遠古知識精煉藥劑", additional_info = "需要等級 60\n[q2]使用: 魔法法術和效果造成的傷害最多提高180點，持續2小時。你在同一時間內只能保有一種精煉藥劑的效果。此效果在死亡之後仍然有效。 (3秒 冷卻)"},
